-- 20260508_lock_search_path_security_definer.sql
-- Lock search_path on all public SECURITY DEFINER functions owned by postgres.
-- Skips PostGIS / extension-owned fns we cannot ALTER.
-- Without locking, a user with CREATE on any schema in search_path could
-- shadow references inside SECURITY DEFINER functions and execute as the owner.

